// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: bounce off top of brick (flip vy)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  // Ball moving UP, hits bottom of brick
  state.ball = { x: 125, y: 122, r: 7, vx: 0, vy: -100 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy should flip to DOWN');
  assert.ok(brick.alive === false, 'brick should be destroyed');
});

test('step: bounce off side of brick (flip vx)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  // Ball moving RIGHT, hits left side of brick
  state.ball = { x: 90, y: 110, r: 7, vx: 100, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT');
  assert.ok(brick.alive === false, 'brick should be destroyed');
});

test('step: bounce off corner of brick (flip both)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  // Ball moving RIGHT-DOWN, hits top-left corner
  // Penetration should be equal on both axes
  state.ball = { x: 98, y: 102, r: 7, vx: 100, vy: 100 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT');
  assert.ok(state.ball.vy < 0, 'vy should flip to UP');
  assert.ok(brick.alive === false, 'brick should be destroyed');
});

test('step: push out (avoid sticky bounce)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  state.ball = { x: 125, y: 122, r: 7, vx: 0, vy: -100 };
  step(state, 1 / 60);
  // After bounce, ball.y + ball.r should be <= brick.y + brick.h
  assert.ok(state.ball.y + state.ball.r <= brick.y + brick.h, 'ball should be pushed out of the brick');
});

test('step: neighbours (bounce only once)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  brick1.x = 100; brick1.y = 100; brick1.w = 50; brick1.h = 20;
  brick2.x = 158; brick2.y = 100; brick2.w = 50; brick2.h = 20;
  // Ball positioned to hit the seam between two bricks
  state.ball = { x: 154, y: 110, r: 7, vx: 100, vy: 0 };
  step(state, 1 / 60);
  // If it bounces twice, vx will be positive again. It should be negative.
  assert.ok(state.ball.vx < 0, 'vx should only flip once even if hitting two bricks');
});

test('step: tunnelling (high speed collision)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  // Ball is at y=140, moving UP at 1000 px/s.
  // In 0.05s (max dt), it moves 50px to y=90.
  // Brick is at y=100, height=20. It jumps from 140 to 90, potentially skipping the brick if not sweeping.
  state.ball = { x: 125, y: 140, r: 7, vx: 0, vy: -1000 };
  step(state, 0.05);
  assert.ok(brick.alive === false, 'brick should be destroyed even if ball tunneled through');
  assert.ok(state.ball.vy > 0, 'vy should flip to DOWN');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

